package io.github.trolanin.drift;

import java.lang.reflect.Field;
import java.lang.reflect.Modifier;

/**
 * Slots in the uniform vec4 P[] array shared by every shader pass (the phone cousin of params.h).
 * Slot s lives in P[s / 4], component s % 4. The shaders get a "#define S_NAME n" for every
 * field here, generated by {@link #glslDefines()}, so add new slots here and nowhere else.
 */
final class Params {
    private Params() { }

    static final int RES_X = 0, RES_Y = 1, ASPECT = 2, TIME = 3;
    // feedback warp (already scaled to this frame's length)
    static final int ZOOM = 4, ROT = 5, SWIRL = 6, WARP = 7, WARP_FREQ = 8, WARP_PHASE = 9, DRIFT_X = 10, DRIFT_Y = 11;
    static final int DECAY = 12, HUE = 13, MIRROR_X = 14, MIRROR_Y = 15;
    // colour palette: 0.5 + 0.5 * cos(2pi * (C * t + D))
    static final int PAL_C0 = 16, PAL_C1 = 17, PAL_C2 = 18, PAL_PHASE = 19, PAL_D0 = 20, PAL_D1 = 21, PAL_D2 = 22, PAL_SPREAD = 23;
    // layers drawn into the feedback
    static final int SPEC_RING = 24, SPEC_RADIUS = 25, TUNNEL = 26, TUNNEL_SIDES = 27, SPARKLE = 28, ORBS = 29, ORB_PHASE = 30, ADD = 31;
    static final int BASS = 32, MID = 33, TREB = 34, LEVEL = 35;
    // waveform shape weights and look
    static final int W_CIRCLE = 36, W_LINE = 37, W_SCOPE = 38, W_SPIRAL = 39, W_ROSE = 40, W_LISS = 41;
    static final int ROSE_K = 42, LISS_A = 43, LISS_B = 44, LISS_PHASE = 45;
    static final int WAVE_SCALE = 46, WAVE_GAIN = 47, WAVE_THICK = 48, WAVE_ANGLE = 49, WAVE_BRIGHT = 50, COPIES = 51, COPY_ALPHA = 52;
    // flame warp and curl flow (feedback)
    static final int FLAME = 53, VAR_A = 54, VAR_B = 55, VAR_MIX = 56, AFF_ROT = 57, AFF_SCALE = 58, AFF_X = 59, AFF_Y = 60;
    static final int FLOW = 61, FLOW_SCALE = 62, FLOW_PHASE = 63;
    // composite: kaleidoscope, chromatic split, echo, tone
    static final int KA = 64, KAMT = 65, KSPIN = 66, CHROMA = 67, ECHO = 68, ECHO_ZOOM = 69, ECHO_ANGLE = 70;
    static final int BRIGHT = 71, FLASH = 72, VIGNETTE = 73, SAT = 74, BLACK = 75;
    // complex lens and wallpaper tiling (composite)
    static final int VIEW = 76, VIEW_AMT = 77, VIEW_P1 = 78, VIEW_PHASE = 79, TILE = 80, TILE_AMT = 81, TILE_SCALE = 82;
    // strange attractor points
    static final int ATTR_FAM = 83, ATTR_BRIGHT = 84, ATTR_SCALE = 85, ATTR_SPIN = 86, ATTR_SIZE = 87;
    static final int ATTR_A = 88, ATTR_B = 89, ATTR_C = 90, ATTR_D = 91, ATTR_SEED = 92, ATTR_ITER = 93;
    // tunnel rings: 8 x (radius, strength), two rings per vec4. Must start on a multiple of 4.
    static final int RINGS = 96;

    /** Floats in P[]: the last slot used, rounded up to whole vec4s. */
    static final int FLOATS = 112;
    static final int VEC4S = FLOATS / 4;

    /** "#define S_NAME n" for every slot above, plus NP (the vec4 count). */
    static String glslDefines() {
        StringBuilder sb = new StringBuilder();
        for (Field f : Params.class.getDeclaredFields()) {
            int m = f.getModifiers();
            if (!Modifier.isStatic(m) || f.getType() != int.class) continue;
            try {
                if (f.getName().equals("FLOATS") || f.getName().equals("VEC4S")) continue;
                sb.append("#define S_").append(f.getName()).append(' ').append(f.getInt(null)).append('\n');
            } catch (IllegalAccessException e) { throw new RuntimeException(e); }
        }
        sb.append("#define NP ").append(VEC4S).append('\n');
        return sb.toString();
    }
}
